        response = await fetch(url, { ...baseInit, proxy });
      } catch (proxyError) {
        if (!proxy) throw proxyError;
        log4("fetchAvailableModels via proxy failed, retrying directly: " + String(proxyError));
        response = await fetch(url, baseInit);
      }
      if (!response.ok) continue;
      return await response.json();
    } catch (error) {
      log4("fetchAvailableModels failed at " + baseEndpoint + ": " + String(error));
      continue;
    }
  }
